def test_user_registration_with_valid_data(client):
    response = client.post("/api/auth/signup", json={
        "email": "testuser@example.com",
        "password": "securepassword123"
    })
    assert response.status_code == 201
    assert "message" in response.json()
    assert response.json()["message"] == "User created successfully"

def test_user_login_with_valid_credentials(client):
    # First register user
    client.post("/api/auth/signup", json={
        "email": "testuser@example.com",
        "password": "securepassword123"
    })

    response = client.post("/api/auth/login", json={
        "email": "testuser@example.com",
        "password": "securepassword123"
    })
    assert response.status_code == 200
    assert "token" in response.json()

def test_create_expense_with_valid_data(client, authenticated_token):
    headers = {"Authorization": f"Bearer {authenticated_token}"}
    response = client.post("/api/expenses", json={
        "amount": 99.99,
        "date": "2023-10-01",
        "category": "Food",
        "notes": "Lunch"
    }, headers=headers)
    assert response.status_code == 201
    assert "id" in response.json()

def test_get_user_expenses_list(client, authenticated_token):
    headers = {"Authorization": f"Bearer {authenticated_token}"}
    response = client.get("/api/expenses", headers=headers)
    assert response.status_code == 200
    assert "expenses" in response.json()
    assert "total" in response.json()

def test_category_validation_on_expense_creation(client, authenticated_token):
    headers = {"Authorization": f"Bearer {authenticated_token}"}
    response = client.post("/api/expenses", json={
        "amount": 50.00,
        "date": "2023-10-01",
        "category": "InvalidCategory",
        "notes": "Test"
    }, headers=headers)
    assert response.status_code == 422
    assert "error" in response.json()
